using ClinicHub.Domain.Attachments;
using ClinicHub.Domain.Common;
using ClinicHub.Domain.Identity;
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;

namespace ClinicHub.Infrastructure.Database.Configurations.Attachments;

/// <summary>The clinic FK and filter come from <c>AppDbContext</c> (<see cref="IClinicOrShared"/>).</summary>
public class AttachmentConfiguration : IEntityTypeConfiguration<Attachment>
{
    public void Configure(EntityTypeBuilder<Attachment> builder)
    {
        // Generated by the service: the file on disk is written before the row exists
        builder.Property(x => x.Id).ValueGeneratedNever();
        builder.Property(x => x.Module).IsRequired().HasMaxLength(FieldLimits.AttachmentModuleMaxLength);
        builder.Property(x => x.RefId).IsRequired().HasMaxLength(FieldLimits.AttachmentRefIdMaxLength);
        builder.Property(x => x.OriginalFileName).IsRequired().HasMaxLength(FieldLimits.AttachmentFileNameMaxLength);
        builder.Property(x => x.TypeKey).IsRequired().HasMaxLength(FieldLimits.AttachmentTypeKeyMaxLength);
        builder.Property(x => x.StorageKey).IsRequired().HasMaxLength(FieldLimits.AttachmentStorageKeyMaxLength);

        builder.HasOne<User>().WithMany().HasForeignKey(x => x.CreatedByUserId).OnDelete(DeleteBehavior.Restrict);
        builder.HasOne<User>().WithMany().HasForeignKey(x => x.DeletedByUserId).OnDelete(DeleteBehavior.Restrict);

        builder.HasIndex(x => x.StorageKey).IsUnique();
        builder.HasIndex(x => new { x.ClinicId, x.Module, x.RefId });
    }
}
